        >> {
  formatting_range<Char> formatting;

  template <typename ParseContext>
  FMT_CONSTEXPR auto parse(ParseContext& ctx) -> decltype(ctx.begin()) {
    return formatting.parse(ctx);
  }

  template <
      typename FormatContext, typename U,
      FMT_ENABLE_IF(
          std::is_same<U, conditional_t<detail::has_const_begin_end<T>::value,
                                        const T, T>>::value)>
  auto format(U& values, FormatContext& ctx) -> decltype(ctx.out()) {
    auto out = detail::copy(formatting.prefix, ctx.out());
    size_t i = 0;
    auto it = std::begin(values);
    auto end = std::end(values);
    for (; it != end; ++it) {
      if (i > 0) out = detail::write_delimiter(out);
      out = detail::write_range_entry<Char>(out, *it);
      ++i;
    }
    return detail::copy(formatting.postfix, out);
  }
};

template <typename Char, typename... T> struct tuple_join_view : detail::view {
  const std::tuple<T...>& tuple;
  basic_string_view<Char> sep;

  tuple_join_view(const std::tuple<T...>& t, basic_string_view<Char> s)
      : tuple(t), sep{s} {}
};

template <typename Char, typename... T>
using tuple_arg_join = tuple_join_view<Char, T...>;

template <typename Char, typename... T>
struct formatter<tuple_join_view<Char, T...>, Char> {
  template <typename ParseContext>
  FMT_CONSTEXPR auto parse(ParseContext& ctx) -> decltype(ctx.begin()) {
    return ctx.begin();
  }

  template <typename FormatContext>
  auto format(const tuple_join_view<Char, T...>& value, FormatContext& ctx) ->
      typename FormatContext::iterator {
    return format(value, ctx, detail::make_index_sequence<sizeof...(T)>{});
  }

 private:
  template <typename FormatContext, size_t... N>
  auto format(const tuple_join_view<Char, T...>& value, FormatContext& ctx,
              detail::index_sequence<N...>) ->
      typename FormatContext::iterator {
    using std::get;
    return format_args(value, ctx, get<N>(value.tuple)...);
  }

  template <typename FormatContext>
  auto format_args(const tuple_join_view<Char, T...>&, FormatContext& ctx) ->
      typename FormatContext::iterator {
    // NOTE: for compilers that support C++17, this empty function instantiation
    // can be replaced with a constexpr branch in the variadic overload.
    return ctx.out();
  }

  template <typename FormatContext, typename Arg, typename... Args>
  auto format_args(const tuple_join_view<Char, T...>& value, FormatContext& ctx,
                   const Arg& arg, const Args&... args) ->
      typename FormatContext::iterator {
    using base = formatter<typename std::decay<Arg>::type, Char>;

    const auto remaining_args = sizeof...(Args);
    auto element_formatter = base();
    auto out = element_formatter.format(arg, ctx);

    if (remaining_args == 0) {
      return out;
    }

    const auto sep_begin = value.sep.begin();
    const auto sep_end = value.sep.end();
    const auto sep_size = value.sep.size();

    if (sep_size == 0) {
      ctx.advance_to(out);
      return format_args(value, ctx, args...);
    }

    if (detail::const_check(sizeof(Char) == 1) && detail::is_utf8()) {
      if (sep_size <= 4) {
        Char local_sep[4];
        size_t local_count = 0;
        while (local_count < sep_size) {
          local_sep[local_count] = static_cast<Char>(sep_begin[local_count]);
          ++local_count;
        }
        if (local_count == 1) {
          *out++ = local_sep[0];
        } else if (local_count == 2) {
          *out++ = local_sep[0];
          *out++ = local_sep[1];
        } else if (local_count == 3) {
          *out++ = local_sep[0];
          *out++ = local_sep[1];
          *out++ = local_sep[2];
        } else {
          size_t written = 0;
          while (written < local_count) {
            *out++ = local_sep[written];
            ++written;
          }
        }
      } else {
        auto src = sep_begin;
        auto chars_left = sep_size;
        while (chars_left > 0) {
          auto first = static_cast<unsigned char>(*src);
          int cp_len = detail::code_point_length(src);
          if (first < 0x80) {
            cp_len = 1;
          }
          if (static_cast<size_t>(cp_len) > chars_left) {
            cp_len = static_cast<int>(chars_left);
          }
          out = detail::copy_str<Char>(src, src + cp_len, out);
          src += cp_len;
          chars_left -= static_cast<size_t>(cp_len);
        }
      }
    } else if (sep_size == 1) {
      *out++ = static_cast<Char>(*sep_begin);
    } else if (sep_size == 2) {
      out = detail::copy(value.sep, out);
    } else {
      out = detail::copy_str_noinline<Char>(sep_begin, sep_end, out);
    }

    ctx.advance_to(out);
    return format_args(value, ctx, args...);
  }
};

FMT_MODULE_EXPORT_BEGIN

/**
  \rst
  Returns an object that formats `tuple` with elements separated by `sep`.

  **Example**::

    std::tuple<int, char> t = {1, 'a'};
    fmt::print("{}", fmt::join(t, ", "));
    // Output: "1, a"
  \endrst
 */
template <typename... T>
FMT_CONSTEXPR auto join(const std::tuple<T...>& tuple, string_view sep)
    -> tuple_join_view<char, T...> {
  return {tuple, sep};
}

template <typename... T>
FMT_CONSTEXPR auto join(const std::tuple<T...>& tuple,
                        basic_string_view<wchar_t> sep)
    -> tuple_join_view<wchar_t, T...> {
  return {tuple, sep};
}

/**
  \rst
  Returns an object that formats `initializer_list` with elements separated by
  `sep`.

  **Example**::

    fmt::print("{}", fmt::join({1, 2, 3}, ", "));
    // Output: "1, 2, 3"
  \endrst
 */
template <typename T>
auto join(std::initializer_list<T> list, string_view sep)
    -> join_view<const T*, const T*> {
  return join(std::begin(list), std::end(list), sep);
}

FMT_MODULE_EXPORT_END
FMT_END_NAMESPACE

#endif  // FMT_RANGES_H_

