template <typename Char, typename... T>
struct formatter<tuple_join_view<Char, T...>, Char> {
  template <typename ParseContext>
  FMT_CONSTEXPR auto parse(ParseContext& ctx) -> decltype(ctx.begin()) {
    return do_parse(ctx, std::integral_constant<size_t, sizeof...(T)>());
  }

  template <typename FormatContext>
  auto format(const tuple_join_view<Char, T...>& value, FormatContext& ctx) ->
      typename FormatContext::iterator {
    return do_format(value, ctx,
                     std::integral_constant<size_t, sizeof...(T)>());
  }

 private:
  std::tuple<formatter<typename std::decay<T>::type, Char>...> formatters_;

  template <typename ParseContext>
  FMT_CONSTEXPR auto do_parse(ParseContext& ctx,
                              std::integral_constant<size_t, 0>)
      -> decltype(ctx.begin()) {
    return ctx.begin();
  }

  template <typename ParseContext, size_t N>
  FMT_CONSTEXPR auto do_parse(ParseContext& ctx,
                              std::integral_constant<size_t, N>)
      -> decltype(ctx.begin()) {
    auto end = std::get<sizeof...(T) - N>(formatters_).parse(ctx);
    if (N > 1) {
      auto end1 = do_parse(ctx, std::integral_constant<size_t, N - 1>());
      if (end != end1)
        FMT_THROW(format_error("incompatible format specs for tuple elements"));
    }
    return end;
  }

  template <typename FormatContext>
  auto do_format(const tuple_join_view<Char, T...>&, FormatContext& ctx,
                 std::integral_constant<size_t, 0>) ->
      typename FormatContext::iterator {
    return ctx.out();
  }

  template <typename FormatContext, size_t N>
  auto do_format(const tuple_join_view<Char, T...>& value, FormatContext& ctx,
                 std::integral_constant<size_t, N>) ->
      typename FormatContext::iterator {
    auto out = std::get<sizeof...(T) - N>(formatters_)
                   .format(std::get<sizeof...(T) - N>(value.tuple), ctx);
    ctx.advance_to(out);
    if (N > 1) {
      out = write_sep(value.sep, out);
      ctx.advance_to(out);
    }
    return do_format(value, ctx, std::integral_constant<size_t, N - 1>());
  }

  template <typename OutputIt>
  auto write_sep(basic_string_view<Char> sep, OutputIt out) -> OutputIt {
    const auto sep_begin = sep.begin();
    const auto sep_end = sep.end();
    const auto sep_size = sep.size();

    if (sep_size == 0) {
      return out;
    }

    if (detail::const_check(sizeof(Char) == 1) && detail::is_utf8()) {
      if (sep_size <= 4) {
        Char local_sep[4];
        size_t local_count = 0;
        while (local_count < sep_size) {
          local_sep[local_count] = static_cast<Char>(sep_begin[local_count]);
          ++local_count;
        }
        if (local_count == 1) {
          *out++ = local_sep[0];
        } else if (local_count == 2) {
          *out++ = local_sep[0];
          *out++ = local_sep[1];
        } else if (local_count == 3) {
          *out++ = local_sep[0];
          *out++ = local_sep[1];
          *out++ = local_sep[2];
        } else {
          size_t written = 0;
          while (written < local_count) {
            *out++ = local_sep[written];
            ++written;
          }
        }
      } else {
        auto src = sep_begin;
        auto chars_left = sep_size;
        while (chars_left > 0) {
          auto first = static_cast<unsigned char>(*src);
          int cp_len = detail::code_point_length(src);
          if (first < 0x80) {
            cp_len = 1;
          }
          if (static_cast<size_t>(cp_len) > chars_left) {
            cp_len = static_cast<int>(chars_left);
          }
          out = detail::copy_str<Char>(src, src + cp_len, out);
          src += cp_len;
          chars_left -= static_cast<size_t>(cp_len);
        }
      }
    } else if (sep_size == 1) {
      *out++ = static_cast<Char>(*sep_begin);
    } else if (sep_size == 2) {
      out = detail::copy(sep, out);
    } else {
      out = detail::copy_str_noinline<Char>(sep_begin, sep_end, out);
    }

    return out;
  }
};

